const SELECTOR = "[data-reco-placement]";
const FEED_URL = "tp/reco/feed.js";

const work = window.__benchmarkWork;
const seen = new WeakSet();
let feedLoaded = null;

const api = (window.tpReco = window.tpReco || { queue: [], mount(container) {
    api.queue.push(container);
} });

function loadFeed() {
    if (feedLoaded)
        return feedLoaded;
    feedLoaded = new Promise((resolve) => {
        const script = document.createElement("script");
        script.async = true;
        script.src = FEED_URL;
        script.addEventListener("load", resolve);
        script.addEventListener("error", resolve);
        document.head.appendChild(script);
    });
    work?.track(feedLoaded);
    return feedLoaded;
}

function claim(container) {
    if (seen.has(container))
        return;
    seen.add(container);
    loadFeed();
    api.mount(container);
}

function scan(root) {
    if (root.matches?.(SELECTOR))
        claim(root);
    if (root.querySelectorAll) {
        for (const container of root.querySelectorAll(SELECTOR))
            claim(container);
    }
}

function observe() {
    scan(document);
    const observer = new MutationObserver((records) => {
        for (const record of records) {
            for (const node of record.addedNodes) {
                if (node.nodeType === 1 && !node.closest("[data-reco-state]"))
                    scan(node);
            }
        }
    });
    observer.observe(document.body, { childList: true, subtree: true });
}

if (document.body)
    observe();
else
    document.addEventListener("DOMContentLoaded", observe, { once: true });
work?.settled("reco-loader");
